function numberOfSets(n, k) {
  const MOD = 1e9 + 7;
  let free = new Array(k + 1).fill(0);
  let inside = new Array(k + 1).fill(0);
  free[0] = 1;

  for (let edge = 0; edge < n - 1; edge++) {
    const nextFree = new Array(k + 1).fill(0);
    const nextInside = new Array(k + 1).fill(0);
    for (let j = 0; j <= k; j++) {
      nextFree[j] = (free[j] + inside[j]) % MOD;
      nextInside[j] = inside[j];
      if (j > 0) {
        nextInside[j] = (nextInside[j] + free[j - 1] + inside[j - 1]) % MOD;
      }
    }
    free = nextFree;
    inside = nextInside;
  }
  return (free[k] + inside[k]) % MOD;
}

