function numberOfSets(n, k) {
  // Known closed form: the answer is C(n + k - 1, 2k), computed exactly with BigInt.
  const top = BigInt(n + k - 1);
  const pick = BigInt(2 * k);
  let ways = 1n;
  for (let i = 1n; i <= pick; i++) ways = ways * (top - pick + i) / i;
  return Number(ways % 1000000007n);
}

